arguments.file_text:
@rendermode InteractiveServer
@using RecipeCommunity.Models

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
              @onmouseover="() => _hoveredStar = star"
              @onmouseout="() => _hoveredStar = 0"
              @onclick="() => SubmitRating(star)">
            &#9733;
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    <div class="current-rating">
        Average: @Recipe.AverageRating / 5 (@Recipe.RatingCount ratings)
    </div>
</div>

@code {
    [Parameter] public Recipe Recipe { get; set; } = default!;

    private int _hoveredStar;
    private int _selectedStar;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        _selectedStar = stars;
        RecipeStore.AddRating(Recipe.Id, stars);
        _submitted = true;
    }
}

.star-rating {
    margin: 1.5rem 0;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.rating-label {
    font-weight: 600;
    margin-right: 0.5rem;
}

.star {
    font-size: 2rem;
    cursor: pointer;
    color: #ddd;
    transition: color 0.15s;
}

.star.hovered,
.star.selected {
    color: #ffc107;
}

.rating-thanks {
    margin-left: 1rem;
    color: #28a745;
    font-weight: 600;
}

.current-rating {
    margin-top: 0.5rem;
    font-size: 0.9rem;
    color: #666;
}

