{"path": "/tmp/sv-e8524f02527b41d2ad24b5c46a784a1e/RecipeCommunity/Models/Recipe.cs", "file_text": "namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

public static class RecipeStore
{
    private static readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F\n2. Roll out dough into a circle\n3. Spread crushed tomatoes evenly\n4. Tear mozzarella and distribute\n5. Bake for 10-12 minutes\n6. Top with fresh basil and olive oil", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook pasta in salted water\n2. Crisp guanciale in a pan\n3. Whisk eggs with grated pecorino\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture\n6. Season with black pepper", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or broil chicken until charred\n3. Sauté garlic and ginger\n4. Add tomato sauce and spices\n5. Simmer, then add cream\n6. Add chicken pieces and cook 5 minutes", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs", Steps = "1. Soak rice noodles in warm water\n2. Make sauce: tamarind, fish sauce, sugar\n3. Stir-fry tofu until golden\n4. Scramble eggs in the wok\n5. Add noodles and sauce, toss\n6. Top with peanuts, sprouts, and lime", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Dice onion, tomato, jalapeño\n4. Chop cilantro\n5. Mix all ingredients together\n6. Season with salt and lime juice", AverageRating = 4.7, RatingCount = 25 },
        new Recipe { Id = 6, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nCheddar cheese\nSour cream\nSalsa\nTomato", Steps = "1. Brown ground beef in a skillet\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm tortillas\n5. Assemble tacos with toppings\n6. Serve with salsa and sour cream", AverageRating = 4.4, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla\nFlour\nBaking soda\nSalt\nChocolate chips", Steps = "1. Cream butter and sugars\n2. Beat in eggs and vanilla\n3. Mix flour, baking soda, salt\n4. Combine wet and dry ingredients\n5. Fold in chocolate chips\n6. Bake at 375°F for 9-11 minutes", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 8, Title = "Miso Soup", Category = "Asian", Ingredients = "Dashi stock\nMiso paste\nTofu\nWakame seaweed\nGreen onions", Steps = "1. Heat dashi stock\n2. Cut tofu into small cubes\n3. Rehydrate wakame\n4. Remove from heat\n5. Dissolve miso paste into broth\n6. Add tofu and wakame, garnish with green onions", AverageRating = 4.2, RatingCount = 10 },
    };

    public static IReadOnlyList<Recipe> All => _recipes;

    public static IEnumerable<string> Categories =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c);

    public static IEnumerable<Recipe> ByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public static void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null) return;
        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public static void Add(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}
"}

