arguments.new_str:
@page "/"
@using RecipeCommunity.Models

<PageTitle>Recipe Community</PageTitle>

<div class="hero">
    <h1>🍳 Recipe Community</h1>
    <p class="lead">Discover, share, and rate delicious recipes from around the world.</p>
</div>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in RecipeStore.Categories)
    {
        <a href="/recipes/@category.ToLower()" class="category-card">
            <h3>@GetCategoryEmoji(category) @category</h3>
            <p>@RecipeStore.ByCategory(category).Count() recipes</p>
        </a>
    }
</div>

<h2 class="mt-4">Recent Favorites</h2>
<div class="recipe-list">
