{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" class="recipe-form">
        <DataAnnotationsValidator />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeStore.Categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" rows="6"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" rows="6"
                placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
        </div>

        <button type="submit" class="btn-submit" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission _model = new();
    private bool _submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(_model.Title) &&
        !string.IsNullOrWhiteSpace(_model.Category) &&
        !string.IsNullOrWhiteSpace(_model.Ingredients) &&
        !string.IsNullOrWhiteSpace(_model.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;
        RecipeStore.Add(_model);
        _submitted = true;
    }
}

